
begin;
create temp table checks(label text);
create function pg_temp.check(ok boolean,label text)returns void language plpgsql as $$begin if ok is not true then raise exception 'FAIL: %',label;end if;insert into checks values(label);end$$;
create temp table fixture(property_id uuid,other_property uuid,actor uuid,contact_id uuid,change_id uuid);
insert into fixture values(gen_random_uuid(),gen_random_uuid(),'11111111-1111-1111-1111-111111111111',gen_random_uuid(),gen_random_uuid());
insert into public.properties(id,name,org_id,address,settings,pet_policy,parking_info,office_hours,social_media,amenities)select property_id,'Property edit SQL fixture','22222222-2222-2222-2222-222222222222'::uuid,'{"street":"Old road","city":"Old city","country":"CA"}'::jsonb,'{"city":"Legacy selector city","additionalUrls":["https://example.test/facts"],"preserveSetting":"keep"}'::jsonb,'{"allowed":true}'::jsonb,'{"garage":true}'::jsonb,'{"monday":"9-5"}'::jsonb,'{"instagram":"retained"}'::jsonb,array['Pool']from fixture union all select other_property,'Other property edit SQL fixture','22222222-2222-2222-2222-222222222222'::uuid,'{}'::jsonb,'{}'::jsonb,'{}'::jsonb,'{}'::jsonb,'{}'::jsonb,'{}'::jsonb,array[]::text[]from fixture;
insert into public.property_contacts(id,property_id,contact_type,name,email,is_primary,billing_address,special_instructions,needs_w9)select contact_id,property_id,'primary','Original contact','fixture@example.test',true,'{"street":"Billing lane","city":"Billing city","country":"CA"}'::jsonb,'Retain this instruction',true from fixture;
insert into public.property_chatbot_contexts(property_id,status,context_markdown,context_json,version,last_generated_at)select property_id,'current','Original property facts','{"original":true}',3,clock_timestamp()from fixture;
insert into public.integration_credentials(property_id,platform,status,account_id,account_name,credentials)select property_id,'google_ads','verified','original-account','Original ad account','{"access_token":"synthetic-not-a-real-token"}'::jsonb from fixture;
create function pg_temp.input(p_property uuid)returns jsonb language sql as $$select(public.read_property_setup(p_property,'11111111-1111-1111-1111-111111111111')->'snapshot')||jsonb_build_object('expectedHash',public.read_property_setup(p_property,'11111111-1111-1111-1111-111111111111')->>'snapshotHash','reason','Correct synthetic property facts')$$;
create function pg_temp.reject_property_record()returns trigger language plpgsql as $$begin if new.action='property.setup.saved'then raise exception 'Fixture action storage failure';end if;return new;end$$;
do $$declare f fixture;v_input jsonb;v_original jsonb;v_r jsonb;v_id uuid;v_other_contact uuid:=gen_random_uuid();v_created timestamptz;v_context timestamptz;begin select *into f from fixture;
 perform pg_temp.check(not has_function_privilege('authenticated','public.save_property_setup(uuid,uuid,uuid,jsonb)','EXECUTE')and not has_table_privilege('authenticated','public.property_setup_changes','SELECT'),'property editing and private history require the authenticated server path');
 v_r:=public.read_property_setup(f.property_id,f.actor);v_original:=v_r->'snapshot';
 perform pg_temp.check(v_r->>'state'='ready'and v_r->'snapshot'->'profile'->'additionalUrls'='["https://example.test/facts"]'and v_r->'snapshot'->'contacts'->0->>'specialInstructions'='Retain this instruction','the editor receives retained URLs and complete billing/contact fields');
 perform pg_temp.check(position('synthetic-not-a-real-token'in v_r::text)=0 and v_r->'connections'->0->>'status'='verified','connection status is readable without returning credential values');
 update public.profiles set role=null where id=f.actor;
 perform pg_temp.check(public.save_property_setup(gen_random_uuid(),f.property_id,f.actor,v_original||jsonb_build_object('expectedHash',v_r->>'snapshotHash','reason','Attempt missing role'))->>'state'='forbidden','a missing manager role cannot save');
 update public.profiles set role='admin'where id=f.actor;
 v_input:=pg_temp.input(f.property_id);v_input:=jsonb_set(jsonb_set(jsonb_set(v_input,'{profile,name}','"Corrected fixture property"'),'{profile,address,city}','"New city"'),'{contacts,0,name}','"Corrected contact"');v_input:=v_input||'{"connectionRequests":[{"platform":"google_ads","accountId":"proposed-account","accountName":"Proposed account","notes":"A plan only"}]}'::jsonb;
 select created_at into v_created from public.property_contacts where id=f.contact_id;
 v_r:=public.save_property_setup(f.change_id,f.property_id,f.actor,v_input);
 perform pg_temp.check(v_r->>'state'='saved'and(select name='Corrected fixture property'and address->>'city'='New city'and settings->>'city'='New city'from public.properties where id=f.property_id),'property facts and selector city update together');
 perform pg_temp.check((select name='Corrected contact'and created_at=v_created and special_instructions='Retain this instruction'and needs_w9 and billing_address->>'country'='CA' from public.property_contacts where id=f.contact_id),'contacts retain identity, original creation and untouched details');
 perform pg_temp.check((select address->>'country'='CA'and pet_policy='{"allowed":true}'and parking_info='{"garage":true}'and office_hours='{"monday":"9-5"}'and social_media='{"instagram":"retained"}'and settings->>'preserveSetting'='keep'from public.properties where id=f.property_id),'saving visible facts preserves unrelated policies and runtime configuration');
 perform pg_temp.check((select status='verified'and account_id='original-account'and credentials->>'access_token'='synthetic-not-a-real-token'from public.integration_credentials where property_id=f.property_id),'a connection plan cannot rewrite real account identity or credentials');
 perform pg_temp.check((select connection_requests->0->>'accountId'='proposed-account'from public.property_setup_state where property_id=f.property_id),'connection intentions are saved separately');
 perform pg_temp.check((select status='stale'and context_markdown='Original property facts'and context_json='{"original":true}'and version=4 from public.property_chatbot_contexts where property_id=f.property_id)and v_r->'contextInvalidated'='true','changed facts atomically invalidate assistant serving without rewriting old evidence');
 perform pg_temp.check((select before_state->'profile'->>'name'='Property edit SQL fixture'and after_state->'profile'->>'name'='Corrected fixture property'and before_state->'contacts'->0->>'name'='Original contact'from public.property_setup_changes where id=f.change_id),'before and after snapshots retain the original private evidence');
 perform pg_temp.check((select product='property'and evidence='server_confirmed'and position('fixture@example.test'in row_to_json(e)::text)=0 and result->'connectionsActivated'='false'from public.shared_action_events e where id=f.change_id),'shared event confirms the save without private contact text or provider claims');
 perform pg_temp.check(public.save_property_setup(f.change_id,f.property_id,f.actor,v_input)->>'state'='replayed'and(select count(*)=1 from public.property_setup_changes where property_id=f.property_id),'lost save replies do not duplicate changes');
 perform pg_temp.check(public.save_property_setup(f.change_id,f.property_id,f.actor,v_input||'{"reason":"Different decision"}')->>'state'='request_conflict','request replay cannot replace its original reason');
 perform pg_temp.check(public.save_property_setup(gen_random_uuid(),f.property_id,f.actor,v_input)->>'state'='source_changed','stale drafts cannot overwrite the latest property');
 v_input:=pg_temp.input(f.property_id);v_input:=jsonb_set(v_input,'{profile,unitCount}','0');v_r:=public.save_property_setup(gen_random_uuid(),f.property_id,f.actor,v_input);
 perform pg_temp.check(v_r->>'state'='saved'and(select unit_count=0 from public.properties where id=f.property_id),'zero units is preserved rather than changed to unknown');
 v_input:=pg_temp.input(f.property_id);v_input:=jsonb_set(v_input,'{profile,unitCount}','2.5');begin perform public.save_property_setup(gen_random_uuid(),f.property_id,f.actor,v_input);raise exception 'expected fractional rejection';exception when others then if sqlerrm='expected fractional rejection'then raise;end if;end;
 perform pg_temp.check((select unit_count=0 from public.properties where id=f.property_id),'fractional unit input cannot be partially saved');
 insert into public.property_contacts(id,property_id,contact_type,name,email)values(v_other_contact,f.other_property,'secondary','Other contact','other@example.test');v_input:=pg_temp.input(f.property_id);v_input:=jsonb_set(v_input,'{contacts,0,id}',to_jsonb(v_other_contact));
 perform pg_temp.check(public.save_property_setup(gen_random_uuid(),f.property_id,f.actor,v_input)->>'state'='contact_conflict'and(select name='Corrected contact'from public.property_contacts where id=f.contact_id),'contacts cannot be stolen across properties');
 v_input:=pg_temp.input(f.property_id);v_input:=jsonb_set(v_input,'{profile,name}','"Must not save partially"');v_input:=jsonb_set(v_input,'{contacts,0,email}','"bad address"');begin perform public.save_property_setup(gen_random_uuid(),f.property_id,f.actor,v_input);raise exception 'expected contact rejection';exception when others then if sqlerrm='expected contact rejection'then raise;end if;end;
 perform pg_temp.check((select name='Corrected fixture property'from public.properties where id=f.property_id),'invalid contacts reject the entire property save');
 v_id:=gen_random_uuid();v_input:=jsonb_set(pg_temp.input(f.property_id),'{profile,name}','"Must roll back on event failure"');create trigger reject_property_record before insert on public.shared_action_events for each row execute function pg_temp.reject_property_record();
 begin perform public.save_property_setup(v_id,f.property_id,f.actor,v_input);raise exception 'expected atomic action failure';exception when others then if sqlerrm='expected atomic action failure'then raise;end if;end;drop trigger reject_property_record on public.shared_action_events;
 perform pg_temp.check(not exists(select 1 from public.property_setup_changes where id=v_id)and(select name='Corrected fixture property'from public.properties where id=f.property_id),'recording failure rolls back property, contacts and private history together');
 v_input:=pg_temp.input(f.property_id);v_input:=jsonb_set(v_input,'{contacts}','[]');select stale_at into v_context from public.property_chatbot_contexts where property_id=f.property_id;v_r:=public.save_property_setup(gen_random_uuid(),f.property_id,f.actor,v_input);
 perform pg_temp.check(v_r->>'state'='saved'and not exists(select 1 from public.property_contacts where property_id=f.property_id),'empty contact selection deliberately removes all saved contacts');
 perform pg_temp.check(v_r->'contextInvalidated'='false'and(select stale_at=v_context from public.property_chatbot_contexts where property_id=f.property_id),'contact-only edits do not claim a fact regeneration');
 begin update public.property_setup_changes set input='{}'where id=f.change_id;raise exception 'expected immutable change';exception when others then if sqlerrm='expected immutable change'then raise;end if;end;
 perform pg_temp.check((select input->>'reason'='Correct synthetic property facts'from public.property_setup_changes where id=f.change_id),'retained changes cannot be rewritten');
 begin update public.properties set name='Legacy partial bypass'where id=f.property_id;raise exception 'expected recorded property guard';exception when others then if sqlerrm='expected recorded property guard'then raise;end if;end;
 begin insert into public.property_contacts(property_id,contact_type,name,email)values(f.property_id,'secondary','Legacy bypass','legacy@example.test');raise exception 'expected recorded contact guard';exception when others then if sqlerrm='expected recorded contact guard'then raise;end if;end;
 perform pg_temp.check((select name='Corrected fixture property'from public.properties where id=f.property_id)and not exists(select 1 from public.property_contacts where property_id=f.property_id),'older partial writers cannot bypass recorded property or contact saves');

 perform pg_temp.check(public.read_property_setup(f.other_property,f.actor,null,f.change_id)->>'state'='not_found','saved change identity is property scoped');
 update public.profiles set org_id=null where id=f.actor;
 perform pg_temp.check(public.read_property_setup(f.property_id,f.actor)->>'state'='forbidden'and public.save_property_setup(f.change_id,f.property_id,f.actor,v_input)->>'state'='forbidden','read and replay recheck current organization access');
 update public.profiles set org_id='22222222-2222-2222-2222-222222222222'where id=f.actor;
end$$;
do $$declare f fixture;v_r jsonb;v_cursor uuid;v_seen uuid[]:='{}';v_input jsonb;i integer;v_expected bigint;begin select *into f from fixture;
 for i in 1..1005 loop v_input:=pg_temp.input(f.property_id)||jsonb_build_object('reason','Synthetic change '||i);perform public.save_property_setup(gen_random_uuid(),f.property_id,f.actor,v_input);end loop;
 select count(*)into v_expected from public.property_setup_changes where property_id=f.property_id;
 loop v_r:=public.read_property_setup(f.property_id,f.actor,v_cursor);select v_seen||array_agg((x->>'id')::uuid)into v_seen from jsonb_array_elements(v_r->'changes')x;v_cursor:=(v_r->>'nextCursor')::uuid;exit when v_cursor is null;end loop;
 perform pg_temp.check(cardinality(v_seen)=v_expected and(select count(distinct x)=v_expected from unnest(v_seen)x),'history paging reaches all changes beyond1000 without duplicates');
 insert into public.property_contacts(property_id,contact_type,name,email)select f.other_property,'secondary','Fixture contact '||n,'contact'||n||'@example.test'from generate_series(1,1005)n;
 v_r:=public.read_property_setup(f.other_property,f.actor);
 perform pg_temp.check(jsonb_array_length(v_r->'snapshot'->'contacts')=1006,'contact reads do not silently stop at the REST row cap');
 perform pg_temp.check(public.read_property_setup(f.property_id,f.actor,gen_random_uuid())->>'state'='cursor_changed','unrelated history cursors cannot silently skip records');
 update public.properties set settings=jsonb_build_object('additionalUrls',null)where id=f.other_property;v_r:=public.read_property_setup(f.other_property,f.actor);perform pg_temp.check(v_r->'snapshot'->'profile'->'additionalUrls'='[]'::jsonb,'an explicit legacy null URL list reads as absent rather than crashing the editor');
end$$;
select count(*)as passed_assertions from checks;
rollback;
